This Terraform configuration creates an AWS egress-only internet gateway for a VPC. By default, it creates a new IPv6-enabled VPC and attaches the egress-only internet gateway to it. The route table includes an IPv6 default route `::/0` through the egress-only internet gateway, allowing IPv6-enabled instances in associated subnets to initiate outbound internet connections while preventing unsolicited inbound internet traffic.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "Optional existing VPC ID to attach the egress-only internet gateway to. If empty, a new IPv6-enabled VPC is created."
  type        = string
  default     = ""
}

